        cid: '03096',
        cnm: 'cmb_BkHoldyPrincPayDdDecsnCd'
    }); //휴무관련(원금)			
    arrCid.push({
        cid: '03096',
        cnm: 'cmb_BkHoldyDdIntPayMethdCd'
    }); //휴무관련(이자)			
    arrCid.push({
        cid: '01513',
        cnm: 'cmb_CoupnPayMethdCd'
    }); //이자 선/후급			
    arrCid.push({
        cid: '03195',
        cnm: 'cmb_BndIntPayDdBasTpCd'
    }); //이자일지급구분			
    arrCid.push({
        cid: '03512',
        cnm: 'cmb_IntUdwonProcsCd'
    }); //이자원단위 미만처리		
    arrCid.push({
        cid: '03114',
        cnm: 'cmb_BndOddllotddIntBasTpCd'
    }); //단수일 이자기준			
    arrCid.push({
        cid: '01510',
        cnm: 'cmb_BndSaleTpCd'
    }); //매출형태				
    arrCid.push({
        cid: '02253',
        cnm: 'cmb_IntMmendTpCd'
