/********************************************** 
 * 함수명   : fn_SetCreditData
 * 설명       : 신용평가정보를 설정한다.
 ***********************************************/
scwin.fn_SetCreditData = function() {
    $c.stf.setObjectValue(cmb_CreditValuInstCd1, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd1, '0');
    $c.stf.setObjectValue(cmb_SfValuYn1, '');
    $c.stf.setObjectValue(cmb_CreditValuInstCd2, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd2, '0');
    $c.stf.setObjectValue(cmb_SfValuYn2, '');
    $c.stf.setObjectValue(cmb_CreditValuInstCd3, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd3, '0');
    $c.stf.setObjectValue(cmb_SfValuYn3, '');
    $c.stf.setObjectValue(cmb_CreditValuInstCd4, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd4, '0');
    $c.stf.setObjectValue(cmb_SfValuYn4, '');
    var rowcount = dts_Credit.getTotalRow();
    if (rowcount > 0) {
        for (var idx = 1; idx <= rowcount; idx++) {
            if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9201') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd1, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd1, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn1, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9202') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd2, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd2, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn2, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9203') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd3, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd3, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn3, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9204') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd4, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd4, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn4, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            }
        }
    }
};





/********************************************** 
 * 함수명   : fn_SetUdwrtInstData
 * 설명       : 인수기관정보를 설정한다.
 ***********************************************/
scwin.fn_SetUdwrtInstData = function() {
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd1, '0');
    $c.stf.setObjectValue(edt_UdwrtAmt1, '');
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd2, '0');
    $c.stf.setObjectValue(edt_UdwrtAmt2, '');
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd3, '0');
    $c.stf.setObjectValue(edt_UdwrtAmt3, '');
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd4, '0');
    $c.stf.setObjectValue(edt_UdwrtAmt4, '');
    $c.stf.setObjectValue(edt_UdwrtAmt5, '');
    var rowcount = dts_UdwrtInst.getTotalRow();
    if (rowcount >= 1) {
        scwin.fn_SetUdwrtInst(1, cmb_BndUdwrtInstCd1, edt_UdwrtAmt1);
    }
    if (rowcount >= 2) {
        scwin.fn_SetUdwrtInst(2, cmb_BndUdwrtInstCd2, edt_UdwrtAmt2);
    }
    if (rowcount >= 3) {
        scwin.fn_SetUdwrtInst(3, cmb_BndUdwrtInstCd3, edt_UdwrtAmt3);
    }
    if (rowcount >= 4) {
        scwin.fn_SetUdwrtInst(4, cmb_BndUdwrtInstCd4, edt_UdwrtAmt4);
    }
    if (rowcount >= 5) {
        $c.stf.setObjectValue(edt_UdwrtAmt5, dts_UdwrtInst.getCellData(5, 'UDWRT_AMT'));
    }
};



/********************************************** 
 * 함수명   : fn_SetSecutizAsstData
 * 설명       : 유동화자산정보를 설정한다.
 ***********************************************/
scwin.fn_SetSecutizAsstData = function() {
    $c.stf.setObjectValue(cmb_SecutizAsstTpCd1, '0');
    $c.stf.setObjectValue(cmb_AsstHdTpCd1, '0');
    $c.stf.setObjectValue(cmb_AsstHdInstCd2, '0');
    $c.stf.setObjectValue(cmb_AsstAdmInstCd1, '0');
    $c.stf.setObjectValue(cmb_SecutizAsstTpCd2, '0');
    $c.stf.setObjectValue(cmb_AsstHdTpCd2, '0');
    $c.stf.setObjectValue(cmb_AsstHdInstCd2, '0');
    $c.stf.setObjectValue(cmb_AsstAdmInstCd2, '0');
    $c.stf.setObjectValue(cmb_SecutizAsstTpCd3, '0');
    $c.stf.setObjectValue(cmb_AsstHdTpCd3, '0');
    $c.stf.setObjectValue(cmb_AsstHdInstCd2, '0');
    $c.stf.setObjectValue(cmb_AsstAdmInstCd3, '0');
    $c.stf.setObjectValue(txb_AsstHdInstMiscContn, '');
    $c.stf.setObjectValue(txb_AsstHdTpMiscContn, '');
    $c.stf.setObjectValue(txb_AsstAdmInstMiscContn, '');
    $c.stf.setObjectValue(txb_SecutizAsstTpMiscContn, '');
    $c.stf.setObjectValue(txb_AsstHdInstMiscContn, '');
    var rowcount = dts_SecutizAsst.getTotalRow();
    if (rowcount > 0) {
        for (var idx = 1; idx <= rowcount; idx++) {
            if (dts_SecutizAsst.getCellData(idx, 'HD_ASST_ORD') == 1) {
                scwin.fn_SetSecutizAsstTpCd(idx, cmb_SecutizAsstTpCd1);
                scwin.fn_SetSecutizAsstHdTpCd(idx, cmb_AsstHdTpCd1, cmb_AsstHdInstCd1, cmb_AsstAdmInstCd1);
            } else if (dts_SecutizAsst.getCellData(idx, 'HD_ASST_ORD') == 2) {
                scwin.fn_SetSecutizAsstTpCd(idx, cmb_SecutizAsstTpCd2);
                scwin.fn_SetSecutizAsstHdTpCd(idx, cmb_AsstHdTpCd2, cmb_AsstHdInstCd2, cmb_AsstAdmInstCd2);
            } else if (dts_SecutizAsst.getCellData(idx, 'HD_ASST_ORD') == 3) {
                scwin.fn_SetSecutizAsstTpCd(idx, cmb_SecutizAsstTpCd3);
                scwin.fn_SetSecutizAsstHdTpCd(idx, cmb_AsstHdTpCd3, cmb_AsstHdInstCd3, cmb_AsstAdmInstCd3);
            } else if (dts_SecutizAsst.getCellData(idx, 'HD_ASST_ORD') == 4) {
                $c.stf.setObjectValue(txb_SecutizAsstTpMiscContn, dts_SecutizAsst.getCellData(idx, 'SECUTIZ_ASST_TP_MISC_CONTN'));
                $c.stf.setObjectValue(txb_AsstHdTpMiscContn, dts_SecutizAsst.getCellData(idx, 'ASST_HD_TP_MISC_CONTN'));
                $c.stf.setObjectValue(txb_AsstHdInstMiscContn, dts_SecutizAsst.getCellData(idx, 'ASST_HD_INST_MISC_CONTN'));
                $c.stf.setObjectValue(txb_AsstAdmInstMiscContn, dts_SecutizAsst.getCellData(idx, 'ASST_ADM_INST_MISC_CONTN'));
            }
        }
    }
};
scwin.gform_onload = function() {
    $c.stf.showObj(lbl_PopLoc, false); //팝업위치 레이블 숨김
    $c.bns.BnsPanelToGroupBox(pnl_Req); //패널라운드처리(신청)
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo); //패널라운드처리(상세)
    $c.bns.BnsPanelToGroupBox(pnl_Acpt); //패널라운드처리(접수)

    tab_List.setSelectedTabIndex(1);
    scwin.fn_SetParam(); //호출파라미터설정	
    scwin.fn_dtl_sync_Req(); //상세조회

    // 채권신고담당자 조회
    scwin.fn_Search2();
};
scwin.tab_List_OnSelChanged = function(nIndex) {
    scwin.vBndListProcsTpCd = nIndex;
    if (scwin.vBndListProcsTpCd == 2) {
        //탭지정
        tab_Detail.setSelectedTabIndex(1);
        tab_SecutizAsst.setSelectedTabIndex(1);

        //패널라운드처리
        $c.bns.BnsPanelToGroupBox(pnl_IsuInfo);
        $c.bns.BnsPanelToGroupBox(pnl_IsurCond);
        $c.bns.BnsPanelToGroupBox(pnl_RelInst);
        $c.bns.BnsPanelToGroupBox(pnl_CoupnRt);
        $c.bns.BnsPanelToGroupBox(pnl_IsurPrc);
        $c.bns.BnsPanelToGroupBox(pnl_StockRel);
        $c.bns.BnsPanelToGroupBox(pnl_Princint);
        $c.bns.BnsPanelToGroupBox(pnl_Option);
        $c.bns.BnsPanelToGroupBox(pnl_ChgInt);
        $c.bns.BnsPanelToGroupBox(pnl_SplitRedmpt);
        $c.bns.BnsPanelToGroupBox(pnl_SecutizAsst);
        $c.bns.BnsPanelToGroupBox(pnl_SecutizRelInst);
        $c.bns.BnsPanelToGroupBox(pnl_SecutizAsstMisc);
        $c.bns.BnsPanelToGroupBox(pnl_Strip);
        $c.bns.BnsPanelToGroupBox(pnl_Els);

        //탭설정
        scwin.fn_SetDtlTab();
        //콤보설정
        scwin.fn_SetComboCode();
        scwin.fn_dtl_sync(); //상세조회

    } else if (scwin.vBndListProcsTpCd == 1) {
        scwin.fn_dtl_sync_Req();
    }

    // 채권신고담당자 조회
    scwin.fn_Search2();
};
scwin.dts_IsuInfo_OnLoadCompleted = function(rowcount) {
    scwin.vRowCount = rowcount;
    if (scwin.vBndListProcsTpCd == 2) {
        //물가연동채구분
        if (dts_IsuInfo.getCellData(1, 'ISUR_CD') == 'GB035') {
            cmb_InfllnkYn.setDisabled(false);
            edt_IsuDdRefIdx.setDisabled(false);
        } else {
            cmb_InfllnkYn.setDisabled(true);
            edt_IsuDdRefIdx.setDisabled(true);
        }
    }
};
